<div class="content"><section class="title"><div><span class="eyebrow">ORGANIZACIÓN DEL ARCHIVO</span><h1>CATEGORÍAS DE <em>IMÁGENES.</em></h1><p>Crea categorías deportivas y asígnalas a los sets cuando subas fotografías.</p></div></section>
<?php if(!empty($_SESSION['success'])):?><div class="flash success"><?=htmlspecialchars($_SESSION['success']);unset($_SESSION['success']);?></div><?php endif;?><?php if(!empty($_SESSION['error'])):?><div class="flash error"><?=htmlspecialchars($_SESSION['error']);unset($_SESSION['error']);?></div><?php endif;?>
<div class="category-admin-grid"><form class="panel category-form" method="post" action="<?=url('admin/categorias/guardar')?>"><input type="hidden" name="_token" value="<?=csrf()?>"><input type="hidden" name="id" id="categoryId"><div class="panel-head"><div><span class="eyebrow">NUEVA CATEGORÍA</span><h2 id="categoryFormTitle">CREAR CATEGORÍA</h2></div></div><label>NOMBRE<input name="name" id="categoryName" required placeholder="Ej. Atletismo"></label><label>ESTADO<select name="status" id="categoryStatus"><option value="active">Activa</option><option value="inactive">Inactiva</option></select></label><button class="btn btn-primary">GUARDAR CATEGORÍA →</button><button class="btn btn-secondary" id="categoryCancel" type="button" hidden>CANCELAR EDICIÓN</button></form>
<section class="panel"><div class="panel-head"><div><span class="eyebrow">CLASIFICACIÓN</span><h2>CATEGORÍAS REGISTRADAS</h2></div><span class="result-count"><?=count($categories)?> CATEGORÍAS</span></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>NOMBRE</th><th>SLUG</th><th>SETS</th><th>ESTADO</th><th>ACCIONES</th></tr></thead><tbody><?php foreach($categories as $category):?><tr><td><b><?=htmlspecialchars($category['name'])?></b></td><td><small><?=htmlspecialchars($category['slug'])?></small></td><td><b><?=(int)$category['sets_count']?></b></td><td><span class="table-status <?=$category['status']==='active'?'active':'hidden'?>"><?=$category['status']==='active'?'ACTIVA':'INACTIVA'?></span></td><td><div class="table-actions"><button type="button" class="btn btn-edit" data-category='<?=htmlspecialchars(json_encode(['id'=>$category['id'],'name'=>$category['name'],'status'=>$category['status']],JSON_UNESCAPED_UNICODE),ENT_QUOTES)?>'>EDITAR</button><form method="post" action="<?=url('admin/categorias/eliminar')?>" onsubmit="return confirm('¿Eliminar esta categoría?')"><input type="hidden" name="_token" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$category['id']?>"><button class="btn btn-toggle" <?=$category['sets_count']?'disabled':''?>>ELIMINAR</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section></div></div>
<script>const id=document.getElementById('categoryId'),name=document.getElementById('categoryName'),status=document.getElementById('categoryStatus'),title=document.getElementById('categoryFormTitle'),cancel=document.getElementById('categoryCancel');document.querySelectorAll('[data-category]').forEach(button=>button.addEventListener('click',()=>{const item=JSON.parse(button.dataset.category);id.value=item.id;name.value=item.name;status.value=item.status;title.textContent='EDITAR CATEGORÍA';cancel.hidden=false;name.focus();scrollTo({top:0,behavior:'smooth'});}));cancel.addEventListener('click',()=>{id.value='';name.value='';status.value='active';title.textContent='CREAR CATEGORÍA';cancel.hidden=true;});</script>
